import os,glob,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()

def cells(g, sep):
    # split by rows/cols fully of sep
    H,W=len(g),len(g[0])
    rr=[i for i in range(H) if all(x==sep for x in g[i])]
    cc=[j for j in range(W) if all(g[i][j]==sep for i in range(H))]
    def ranges(idx,n):
        out=[];s=None
        for i in range(n):
            if i in idx:
                if s is not None: out.append((s,i)); s=None
            else:
                if s is None: s=i
        if s is not None: out.append((s,n))
        return out
    return ranges(set(rr),H), ranges(set(cc),W)

def shapes(g,sep):
    (rg),(cg)=cells(g,sep)
    out={}
    for a,b in rg:
        for c,d in cg:
            sub=[row[c:d] for row in g[a:b]]
            cols=set(x for r in sub for x in r if x not in (0,sep))
            if len(cols)==1:
                col=cols.pop()
                n=sum(r.count(col) for r in sub)
                out.setdefault(col,[]).append((n,sub,a,c))
    return out

