import json
def transform(g):
    H,W=len(g),len(g[0])
    # find separator value: full rows/cols of a nonzero color
    from collections import Counter
    cnt=Counter(x for r in g for x in r)
    seps=[v for v in cnt if v!=0 and any(all(x==v for x in g[i]) for i in range(H))]
    sep=seps[0] if seps else None
    rr={i for i in range(H) if sep is not None and all(x==sep for x in g[i])}
    cc={j for j in range(W) if sep is not None and all(g[i][j]==sep for i in range(H))}
    def ranges(blocked,n):
        out=[];s=None
        for i in range(n):
            if i in blocked:
                if s is not None: out.append((s,i)); s=None
            elif s is None: s=i
        if s is not None: out.append((s,n))
        return out
    rgs,cgs=ranges(rr,H),ranges(cc,W)
    out=[row[:] for row in g]
    cells={}  # (ri,ci)->(color, content as set of (i,j) offsets, a,c)
    for ri,(a,b) in enumerate(rgs):
        for ci,(c,d) in enumerate(cgs):
            cols={g[i][j] for i in range(a,b) for j in range(c,d) if g[i][j]!=0 and g[i][j]!=sep}
            if len(cols)==1:
                col=cols.pop()
                px=frozenset((i-a,j-c) for i in range(a,b) for j in range(c,d) if g[i][j]==col)
                cells[(ri,ci)]=(col,px,b-a,d-c)
    bycol={}
    for k,(col,px,h,w) in cells.items(): bycol.setdefault(col,{})[k]=px
    def fl(px,w): return frozenset((r,w-1-c) for r,c in px)
    def fu(px,h): return frozenset((h-1-r,c) for r,c in px)
    for col,ks in bycol.items():
        if len(ks)!=3: continue
        rs=[k[0] for k in ks]; cs=[k[1] for k in ks]
        r0,r1=min(rs),max(rs); c0,c1=min(cs),max(cs)
        missing=[(r,c) for r in (r0,r1) for c in (c0,c1) if (r,c) not in ks]
        if len(missing)!=1: continue
        tgt=missing[0]
        # source: mirror partner in same row -> fl; same col -> fu; diagonal -> r180
        if tgt[1]!=c1 and (tgt[0],c1) in ks: src,op=(tgt[0],c1),'fl'
        elif tgt[1]!=c0 and (tgt[0],c0) in ks: src,op=(tgt[0],c0),'fl'
        elif tgt[0]!=r1 and (r1,tgt[1]) in ks: src,op=(r1,tgt[1]),'fu'
        elif tgt[0]!=r0 and (r0,tgt[1]) in ks: src,op=(r0,tgt[1]),'fu'
        else:
            diag=(r1 if tgt[0]==r0 else r0, c1 if tgt[1]==c0 else c0); src,op=diag,'r180'
        col_,px,h,w=cells[src]
        a,b=rgs[tgt[0]]; c,d=cgs[tgt[1]]
        if op=='fl': npx=fl(px,w)
        elif op=='fu': npx=fu(px,h)
        else: npx=fu(fl(px,w),h)
        for (i,j) in npx: out[a+i][c+j]=col
    return out

